if(!piloting){const p=localPlayer(),x=clamp(p.x,bounds.l+.75,bounds.r-.75),y=clamp(p.y,bounds.t+1.13,bounds.b-1.13);if(p.x!==x||p.y!==y)player.setTransform(V(x,y),0)}
