const tintedSprites=new Map();function drawTinted(im,color,sx,sy,sw,sh,x,y,w,h){const id=im.src+color;let c=tintedSprites.get(id);if(!c){c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;const g=c.getContext('2d');g.drawImage(im,0,0);g.globalCompositeOperation='multiply';g.fillStyle=color;g.fillRect(0,0,c.width,c.height);g.globalCompositeOperation='destination-in';g.drawImage(im,0,0);tintedSprites.set(id,c);}ctx.drawImage(c,sx,sy,sw,sh,x,y,w,h);}











