function actionEffect(x,y,color='green',label='',from=localPlayer()){effects.push({x,y,w:1,h:1,life:.5,color,label,from:{x:from.x+facing*.3,y:from.y-.2}});}
function drawActionEffect(e){if(e.kind==='craft')return;const color=e.color==='blue'?'#28baff':e.color==='red'?'#ff2929':'#39ff24',x=e.x+(e.w||1)/2-.5,y=e.y+(e.h||1)/2-.5,r=Math.max(.48,Math.min(1,(e.w||1)*.45)),from=e.from||localPlayer();ctx.save();ctx.globalAlpha=Math.min(1,e.life*5);ctx.strokeStyle=color;ctx.lineWidth=.045;ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(x-r*.65,y-r*.65);ctx.moveTo(from.x,from.y);ctx.lineTo(x+r*.65,y+r*.65);ctx.stroke();ctx.fillStyle=e.color==='blue'?'#28baff44':e.color==='red'?'#ff333344':'#33ff3344';ctx.fillRect(x-.4,y-.4,.8,.8);ctx.lineWidth=.09;for(let i=0;i<4;i++){ctx.beginPath();const a=i*Math.PI/2+clock*2;ctx.arc(x,y,r,a+.15,a+1.2);ctx.stroke();}if(e.label)text(e.label,x,y-r-.17,.25,color);ctx.restore();}
function shredAt(p){if(piloting||tool!=='shredder'||!inventory.shredder)return false;const i=items.find(i=>P.Vec2.distance(i.body.getPosition(),p)<.55);if(!i){toast('Point the shredder at a loose item stack.');return false;}if(P.Vec2.distance(localPlayer(),i.body.getPosition())>3.5){toast('Move closer to shred it.');return false;}let blocked=false;inside.rayCast(localPlayer(),i.body.getPosition(),f=>{if(f.getBody()===interior&&f.getFilterCategoryBits()===1){blocked=true;return 0;}return 1;});if(blocked){toast('A block is in the way.');return false;}const q=i.body.getPosition();facing=q.x<localPlayer().x?-1:1;actionEffect(q.x,q.y,'red',i.count+' x '+NAMES[i.type]);inside.destroyBody(i.body);items.splice(items.indexOf(i),1);save(true);return true;}

// The ammo count sits right against the turret's action box, over the hull wall (side walls); top and bottom turrets keep it just inside.
function ammoLabelPosition(m){const p=mountPoint(m),n=inward(m),k=m.side==='left'||m.side==='right'?.15:1.05;return {x:p.x+n.x*k,y:p.y+n.y*k+.08};}
function terrainHash(x,y){return Math.abs(Math.sin(x*127.1+y*311.7)*43758.5453)%1;}
function finchNoise(x,y){const ix=Math.floor(x),iy=Math.floor(y),u=x-ix,v=y-iy,s=u*u*(3-2*u),t=v*v*(3-2*v);return (terrainHash(ix,iy)*(1-s)+terrainHash(ix+1,iy)*s)*(1-t)+(terrainHash(ix,iy+1)*(1-s)+terrainHash(ix+1,iy+1)*s)*t;}




function fabGaugeLevels(fab){return {iron:clamp((fab?.materials?.iron||0)/64,0,1),explosives:clamp((fab?.materials?.explosives||0)/64,0,1)};}
function drawFabGauges(fab){const levels=fabGaugeLevels(fab); // Legacy source slots: x61..93, y80..85 and y90..95.
for(const [type,y,color,shine] of [['iron',1.5,'#aeb3b8','#e5e8ea'],['explosives',1.75,'#bc2329','#f35355']]){rect(.72,y,.64,.125,'#171717');const width=.64*levels[type];if(width>0){rect(.72,y,width,.125,color);rect(.72,y,width,.025,shine);}}}

// Dungeon, portals and physical cargo (v16).






// The handheld pusher's beam reaches up to 1000 tiles, stopping at the first thing in its path (a wall, block or object).
const HAND_PUSHER_RANGE=1000;
// Right click: on a recycler with anything in hand (a stack, a wrench, a shredder, a handheld pusher...) it recycles
// what you're holding; Shift + right click with the wrench dismantles the recycler. Otherwise the shredder shreds and
// the wrench dismantles. Online the server runs this (the 'remove' action).
function secondaryAt(c){const f=terrainAt(c);if(f?.type==='recycler'&&slots[selected]&&!(keys.shift&&tool==='walk'))return recycleCarried(f);if(tool==='shredder')return shredAt(localMouse());removeAt(c);}
function pushAt(p,dt=1/60){const from=localPlayer().clone(),d=V(p.x-from.x,p.y-from.y);if(d.length()<.01)return;d.normalize();const end=V(from.x+d.x*HAND_PUSHER_RANGE,from.y+d.y*HAND_PUSHER_RANGE);let hit=null,point=end,fraction=1;inside.rayCast(from,end,(f,pt,n,t)=>{const body=f.getBody();if(body===player||f.isSensor())return -1;/* like a stationary pusher's beam: through ladders, walkways and the other tiles beams cross */if(body===interior&&typeof beamPasses==='function'&&beamPasses(f,pt,d))return -1;if(body!==interior&&body.getType()!=='dynamic')return -1;if(t<fraction){fraction=t;hit=body;point=pt.clone();}return t;});pusherVisual={from,to:point,pull:pusherPull,until:clock+.09};if(!hit||hit.getType()!=='dynamic')return;const sign=pusherPull?-1:1;wakeCargo(hit);hit.applyLinearImpulse(V(d.x*sign*hit.getMass()*24*dt,d.y*sign*hit.getMass()*24*dt),hit.getWorldCenter(),true);}
// Handheld pusher beams: your own (local, or from the server when online), your crewmates' and other ships' crews'.
function beamOf(b){return b&&{from:{x:b[0],y:b[1]},to:{x:b[2],y:b[3]},pull:!!b[4]};}
function drawPusherBeam(e=pusherVisual){if(e===pusherVisual&&typeof netActive!=='undefined'&&netActive&&netState){for(const c of netState.crew||[])if(c.beam&&(c.id!==netID||!pusherVisual))drawPusherBeam(beamOf(c.beam));}if(!e)return;const dx=e.to.x-e.from.x,dy=e.to.y-e.from.y,len=Math.hypot(dx,dy),im=spriteImages.pusher_beam;ctx.save();ctx.translate(e.from.x,e.from.y);ctx.rotate(Math.atan2(dy,dx));if(im?.complete&&im.naturalWidth)drawTinted(im,e.pull?'#bb4aff':'#40ff72',0,0,32,32,0,-.4,len,.8);ctx.restore();}




function drawShipFloor(b){rect(b.l-.5,b.t-.5,b.r-b.l+1,b.b-b.t+1,'#c6c6c6');for(let xx=b.l+1;xx<b.r;xx++)for(let yy=b.t+1;yy<b.b;yy++)poly([[xx-.5,yy-.5],[xx+.5,yy+.5],[xx-.5,yy+.5]],(xx+yy)%2?'#c3c5c6':'#bec1c2','#c9c9c9',.015);}
