function drawHealthBar(x,y,width,ratio,label=''){const h=.38;rect(x-width/2,y,width,h,'#101510');const im=spriteImages.hp_bar;if(im?.complete&&im.naturalWidth){ctx.save();ctx.beginPath();ctx.rect(x-width/2,y,width*clamp(ratio,0,1),h);ctx.clip();drawTinted(im,'#36ed25',0,0,256,64,x-width/2,y,width,h);ctx.restore();}else rect(x-width/2,y,width*clamp(ratio,0,1),h,'#36ed25');if(label)text(label,x,y-.12,.25,'#baffad');}

