// Projectiles: a glowing head with a long trail back along the flight path, both from the pack's gradient
// textures tinted per ammo type (AMMO in era.js). Trail length scales with speed (~0.15 s of flight).
function drawProjectile(p,v,type){const a=AMMO[type]||AMMO.ammo,speed=Math.hypot(v?.x||0,v?.y||0);if(!speed)return;const len=Math.min(16,speed*.15),ang=Math.atan2(v.y,v.x),trail=spriteImages['official-thruster_gradient'],glow=spriteImages['official-gradient_circle'];
 ctx.save();ctx.translate(p.x,p.y);ctx.rotate(ang);
 if(trail?.complete&&trail.naturalWidth){for(let k=0;k<3;k++){const from=len*k/3;ctx.globalAlpha=.38;drawTinted(trail,a.trail,0,0,trail.naturalWidth,trail.naturalHeight,-len,-.17,len-from,.34);}ctx.globalAlpha=1;}
 else{ctx.strokeStyle=a.trail;ctx.lineWidth=.22;ctx.globalAlpha=.6;ctx.beginPath();ctx.moveTo(-len,0);ctx.lineTo(0,0);ctx.stroke();ctx.globalAlpha=1;}
 if(glow?.complete&&glow.naturalWidth)drawTinted(glow,a.trail,0,0,glow.naturalWidth,glow.naturalHeight,-.55,-.55,1.1,1.1);
 ctx.fillStyle=a.head;ctx.beginPath();ctx.arc(0,0,.17,0,Math.PI*2);ctx.fill();ctx.restore();}
