function drawBotMarkers(cx,cy,scale,x,y,mw){ctx.save();ctx.font='bold 10px Arial';ctx.textAlign='left';for(const bot of allBots()){const def=BOT_TYPES[bot.species],p=bot.body.getPosition(),bx=cx+p.x*scale,by=cy+p.y*scale,big=bot.species==='green';ctx.fillStyle=def.minimap;ctx.strokeStyle='#101510';ctx.lineWidth=big?2:1;ctx.beginPath();ctx.arc(bx,by,big?4:2.5,0,Math.PI*2);ctx.fill();ctx.stroke();if(big){ctx.strokeStyle=def.minimap;ctx.lineWidth=1;ctx.beginPath();ctx.arc(bx,by,6+Math.sin(clock*4),0,Math.PI*2);ctx.stroke();ctx.fillText(def.tag,Math.min(x+mw-25,bx+8),Math.max(y+24,by-5));}}const greens=zoneData[zone]?.bots?.green?.filter(r=>r?.dead)||[];if(greens.length){ctx.fillStyle=BOT_TYPES.green.minimap;ctx.fillText('Green respawn: '+Math.ceil(Math.min(...greens.map(r=>r.respawn??BOT_RESPAWN_SECONDS)))+'s',x+5,y+25);}ctx.restore();}
