 if(physicsMachineType(type)==='fabricator')drawSprite('official-fabricator',q.x-w/2,q.y-h/2,w,h);else if(type==='recycler'){ctx.translate(q.x-w/2+.5,q.y-h/2+.5);drawStandingMachine('recycler',null);}else if(type==='comms'){ctx.translate(q.x-w/2+.5,q.y-h/2+.5);drawStandingMachine('comms',null);}else drawSprite('official-exbox_base',q.x-w/2,q.y-h/2,w,h);
