// Mission status above the minimap: the running mission and its countdown, or when the next one opens.
function drawMissionStatus(){const m=currentMission();if(!m)return;const mw=m.active&&zoneDef(m.active).clearToEnd?300:190,x=W-mw-14,y=H-120-65-(isCombatZone()?24:6);ctx.save();ctx.font='bold 12px Arial';ctx.textAlign='left';
 const cleared=m.active&&zoneDef(m.active).clearToEnd?' · '+Math.floor((m.cleared||0)*100)+'% / '+Math.round(zoneDef(m.active).clearToEnd*100)+'% mined':'',line=m.active?'MISSION: '+zoneDef(m.active).name+cleared+' · closes in '+missionClock(m.endsIn):'Next mission: '+zoneDef(MISSIONS.rotation[(m.index||0)%MISSIONS.rotation.length]).name+' in '+missionClock(m.nextIn);
 ctx.fillStyle='#000a';ctx.fillRect(x-4,y-13,mw+8,17);ctx.fillStyle=m.active?'#ffd34a':'#cfd8dc';ctx.fillText(line,x,y);ctx.restore();}
// Critical ships are towed home after RETURN_SECONDS: a red countdown in the middle of the screen.
function drawReturnWarning(){if(!(criticalFor>0)||!isCombatZone())return;const left=Math.max(0,RETURN_SECONDS-criticalFor);ctx.save();ctx.font='bold 16px Arial';ctx.textAlign='center';const line='CRITICAL · returning to '+zoneDef(homeFreeport()).name+' in '+missionClock(left);const w=ctx.measureText(line).width;ctx.fillStyle='#000b';ctx.fillRect(W/2-w/2-10,124,w+20,26);ctx.fillStyle=Math.floor(clock*2)%2?'#ff5252':'#ffb3b3';ctx.fillText(line,W/2,143);ctx.restore();}
// Ship naming. A blank name keeps the current one; renames are limited to once per hour.
function openRename(){let d=el('renamebox');if(!d){d=document.createElement('dialog');d.id='renamebox';document.body.appendChild(d);}
 d.innerHTML=`<h2>Rename ship</h2><p>Ships can be renamed once per hour${typeof netActive!=='undefined'&&netActive?' (captain only)':''}. Leave blank for a random name.</p><input id="renameinput" maxlength="32" value=""> <button id="renamerandom">Random</button><p><button id="renameok" class="primary">Rename</button> <button id="renamecancel">Cancel</button></p>`;
 el('renameinput').value=shipName;el('renamerandom').onclick=()=>{el('renameinput').value=randomShipName();};el('renamecancel').onclick=()=>d.close();
 el('renameok').onclick=()=>{const name=cleanShipName(el('renameinput').value)||randomShipName();if(typeof netActive!=='undefined'&&netActive)netAction('rename',{name});else renameShip(name);d.close();};keys={};d.showModal();}
// Leaderboard ("/"): ships ranked by score. On a server it lists every ship there; offline, your own.
let leaderboardRows=null;
function showLeaderboard(){let d=el('leaderboard');if(!d){d=document.createElement('dialog');d.id='leaderboard';document.body.appendChild(d);d.addEventListener('keydown',e=>{if(e.key==='/'){e.preventDefault();d.close();}});}
 if(d.open)return d.close();if(typeof netActive!=='undefined'&&netActive&&typeof networkSend==='function'){leaderboardRows=null;networkSend({type:'leaderboard'});}renderLeaderboard();keys={};d.showModal();}
function renderLeaderboard(){const d=el('leaderboard');if(!d)return;const online=typeof netActive!=='undefined'&&netActive;const rows=online?leaderboardRows:[{name:shipName,score:shipScore,zone:zoneDef().name,crew:1,you:true}];
 d.innerHTML=`<h2>Leaderboard</h2><p>Points: rock ${SCORE.rock} · ore ${SCORE.ore} · treasure ${SCORE.treasure} · bots ${Object.entries(SCORE.bot).map(([k,v])=>k+' '+v).join(', ')} · ${SCORE.pvpPer100} per 100 PvP damage · ${SCORE.missionEnter} per mission entered</p>${rows?`<table class="leaderboard"><tr><th>#</th><th>Ship</th><th>Zone</th><th>Crew</th><th>Score</th></tr>${rows.map((r,i)=>`<tr class="${r.you?'you':''}"><td>${i+1}</td><td>${escapeHTML(r.name)}</td><td>${escapeHTML(r.zone||'')}</td><td>${r.crew??''}</td><td>${(r.score||0).toLocaleString()}</td></tr>`).join('')}</table>`:'<p>Loading…</p>'}${online?'':'<p><small>Offline: only this ship. Join a server to compare ships.</small></p>'}<p><small>Press / or Esc to close.</small></p><button id="closeleaderboard">Close</button>`;
 el('closeleaderboard').onclick=()=>d.close();}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
